import { formatDateTime } from '@sanity/cli-core/dates';
import { SANITY_FUNCTION_PREFIX } from '../../constants.js';
import { styleText } from '../style-text.js';
import { niceId, renderSection } from './presenters.js';
export function formatFunctionsList(functions, options = {}) {
    if (!options.verbose)
        return formatCompactList(functions);
    return functions.map((fn) => formatFunction(fn, options)).join('\n');
}
export function formatFunction(fn, options = {}) {
    if (!options.verbose)
        return formatCompactList([fn]);
    const rows = [];
    if (fn.type)
        rows.push(['Type', shortType(fn.type)]);
    if (fn.updatedAt) {
        const updatedAt = formatDateTime(fn.updatedAt);
        if (updatedAt)
            rows.push(['Updated', updatedAt]);
    }
    if (typeof fn.memory === 'number')
        rows.push(['Memory', `${fn.memory} MB`]);
    if (typeof fn.timeout === 'number')
        rows.push(['Timeout', `${fn.timeout}s`]);
    const rule = formatEventRule(fn.eventRule);
    if (rule)
        rows.push(['Rule', rule]);
    return renderSection(formatTitle(fn), rows);
}
function formatCompactList(functions) {
    const titles = functions.map(plainTitle);
    const ids = functions.map((fn) => `<${fn.id}>`);
    const types = functions.map((fn) => (fn.type ? shortType(fn.type) : '-'));
    const updated = functions.map((fn) => (fn.updatedAt ? formatDateTime(fn.updatedAt) || '-' : '-'));
    const titlePad = Math.max(...titles.map((title) => title.length));
    const idPad = Math.max(...ids.map((id) => id.length));
    const typePad = Math.max(...types.map((type) => type.length));
    return functions
        .map((fn, index) => {
        const title = formatIdentity(fn) + ' '.repeat(titlePad - titles[index].length);
        const id = niceId(fn.id) + ' '.repeat(idPad - ids[index].length);
        const type = styleText('dim', types[index].padEnd(typePad));
        const timestamp = styleText('dim', updated[index]);
        return `  ${title}  ${id}  ${type}  ${timestamp}`;
    })
        .join('\n');
}
function formatTitle(fn) {
    return `${formatIdentity(fn)} ${niceId(fn.id)}`;
}
function formatIdentity(fn) {
    const parts = [];
    if (fn.name)
        parts.push(styleText('bold', fn.name));
    if (fn.displayName && fn.displayName !== fn.name) {
        parts.push(styleText('green', `"${fn.displayName}"`));
    }
    if (parts.length === 0)
        parts.push(styleText('bold', 'Unnamed'));
    return parts.join(' ');
}
function plainTitle(fn) {
    const parts = [];
    if (fn.name)
        parts.push(fn.name);
    if (fn.displayName && fn.displayName !== fn.name)
        parts.push(`"${fn.displayName}"`);
    return parts.length > 0 ? parts.join(' ') : 'Unnamed';
}
function shortType(type) {
    return type.startsWith(SANITY_FUNCTION_PREFIX) ? type.slice(SANITY_FUNCTION_PREFIX.length) : type;
}
function formatEventRule(rule) {
    if (rule === null || rule === undefined)
        return undefined;
    if (typeof rule !== 'object')
        return String(rule);
    if (Array.isArray(rule))
        return rule.map(formatRuleValue).join(', ');
    const entries = Object.entries(rule);
    if (entries.length === 0)
        return undefined;
    return entries.map(([key, value]) => `${key}: ${formatRuleValue(value)}`).join(' · ');
}
function formatRuleValue(value) {
    if (typeof value === 'string')
        return value;
    if (value === null || value === undefined)
        return String(value);
    if (Array.isArray(value))
        return value.map(formatRuleValue).join(', ');
    if (typeof value === 'object')
        return JSON.stringify(value);
    return String(value);
}
